const {briefing}=$('Separar briefings').item.json;
const dossier=$json.briefing?.id===briefing.id?$json.briefing.reporter_dossier:null;
if (dossier) return {json:{briefing:{...briefing,reporter_dossier:dossier}}};
if ($json.error) return {json:{briefing:{...briefing,reporter_dossier:{status:'falha_tecnica',findings:[],open_questions:[],source:null,execution_id:String($execution.id)}}}};
return {json:{briefing}};

const {briefing}=$('Preparar briefing para redação').item.json;
if($json.status!=='completed')throw Error('Redação incompleta.');
const parts=($json.output??[]).flatMap(x=>x.content??[]).filter(x=>x.type==='output_text').map(x=>x.text);
const draft=parts.length===1&&typeof parts[0]==='object'?parts[0]:JSON.parse(parts.join(''));
if(typeof draft?.title!=='string'||!draft.title.trim()||typeof draft.content!=='string'||!draft.content.trim())throw Error('Rascunho inválido.');
if(!Array.isArray(draft.open_questions)||draft.open_questions.some(q=>typeof q!=='string'||!q.trim()))throw Error('Pendências de apuração inválidas.');
const dossier=briefing.reporter_dossier;
const sources=[{id:'rss',text:briefing.source.text}];
if (dossier?.source?.text) sources.push(dossier.source);
const open_questions=[...new Set([...draft.open_questions,...(dossier?.open_questions??[])])];
return {json:{open_questions,mode:'piloto',pauta_id:briefing.id,target_id:briefing.target_id,title:draft.title,content:draft.content,briefing,sources}};
